    AS c(name text,street text,ward text,cat text,phone text,pid text,source text,note text,maps text,key text)
), vetted AS (
  SELECT c.*
  FROM candidates c
  JOIN public.sales_hcm_old_wards w
    ON w.province='TP Hồ Chí Minh' AND w.ward_new=c.ward
   AND w.legacy_district='Quận 6' AND w.active
  WHERE c.cat IN ('nha_sach','van_phong_pham')
    AND c.source LIKE 'https://%'
    AND NOT EXISTS (
      SELECT 1 FROM public.field_prospects p
      WHERE p.research_source_key=c.key
         OR (p.google_place_id IS NOT NULL AND p.google_place_id=c.pid)
         OR (c.phone IS NOT NULL AND p.phone IS NOT NULL
             AND regexp_replace(p.phone,'[^0-9]','','g')=regexp_replace(c.phone,'[^0-9]','','g'))
         OR (p.province='TP Hồ Chí Minh' AND p.district='Quận 6'
             AND (lower(btrim(p.name))=lower(btrim(c.name))
                  OR lower(btrim(split_part(p.address_line,', phường',1)))=lower(btrim(c.street))
                  OR lower(p.address_line) LIKE lower(c.street||',%')))
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.customers k
      WHERE (c.phone IS NOT NULL AND k.phone IS NOT NULL
                AND regexp_replace(k.phone,'[^0-9]','','g')=regexp_replace(c.phone,'[^0-9]','','g'))
         OR (k.province='TP Hồ Chí Minh' AND k.district='Quận 6'
             AND (lower(btrim(k.name))=lower(btrim(c.name))
                  OR lower(k.address_line) LIKE lower(c.street||',%')))
    )
), ins AS (
  INSERT INTO public.field_prospects
    (owner_sub,name,address_line,province,district,category,phone,note,status,source_kind,
     research_source_key,research_source_url,research_batch,ward_new,address_legacy,google_maps_url,google_place_id)
  SELECT 'ef943de4-18f7-49ef-8340-eefb18855534',c.name,
    c.street||', phường '||c.ward||', TP. Hồ Chí Minh',
    'TP Hồ Chí Minh','Quận 6',c.cat,c.phone,
    'Rà nguồn trực tuyến ngày 22/11/2026. '||c.note||
    ' CHƯA GHÉ/CHƯA XÁC MINH bảng hiệu, hoạt động trực tiếp hoặc GPS. Không coi Google Maps Place ID là check-in. Nguồn: '||c.source,
    'new','manual',c.key,c.source,'2026-11-22-hcm-old-q6-round1-184',
    c.ward,c.street||', Quận 6 cũ, TP.HCM cũ',c.maps,c.pid
  FROM vetted c
  ON CONFLICT DO NOTHING
  RETURNING name,ward_new,category
)
SELECT ward_new,category,count(*)::int AS inserted
FROM ins GROUP BY ward_new,category ORDER BY ward_new,category;
